REPLACE INTO dog_personality_modules (id,name,module_order,bind_dimension,description,is_active,created_at,updated_at) VALUES (1, '陌生人耐受度', 1, 'E/I', '评估狗狗在面对非熟悉个体时的社交反馈，用于判定 E 外向 / I 内向社交倾向', 1, '2026-07-13 10:28:02', '2026-07-15 10:35:51');
