REPLACE INTO dog_personality_modules (id,name,module_order,bind_dimension,description,is_active,created_at,updated_at) VALUES (5, '主人服从与自控能力', 5, 'P/J', '评估狗狗对主人指令的响应速度、冲动克制力，用于判定 P 随性好动 / J 规律守序生活偏好', 1, '2026-07-13 10:28:02', '2026-07-15 10:35:51');
REPLACE INTO dog_personality_modules (id,name,module_order,bind_dimension,description,is_active,created_at,updated_at) VALUES (6, '分离情绪与居家行为', 6, 'F/T', '评估狗狗居家独处的情绪、粘人依赖程度，用于判定 F 共情粘人 / T 独立理性情绪表达', 1, '2026-07-13 10:28:02', '2026-07-15 10:35:51');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (1, '陌生人耐受度', 1, 'E/I', 1, '家中来访陌生客人，狗狗的第一反应是？', NULL, NULL, '[{"label": "主动上前嗅闻，摇尾巴，表现友好", "order": 0, "score": 3, "polarity": "+"}, {"label": "站在原地观察，等待主人示意后再靠近", "order": 1, "score": 1, "polarity": "+"}, {"label": "躲到主人身后或角落，表现出紧张", "order": 2, "score": 1, "polarity": "-"}, {"label": "大声吠叫、低吼，甚至做出攻击姿态", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (2, '陌生人耐受度', 1, 'E/I', 2, '陌生人主动伸手，缓慢伸向狗狗头部时，狗狗会？', NULL, NULL, '[{"label": "主动把头凑过去，享受被抚摸", "order": 0, "score": 3, "polarity": "+"}, {"label": "身体僵硬但允许触碰，随后放松", "order": 1, "score": 1, "polarity": "+"}, {"label": "后退躲避，不愿被触碰", "order": 2, "score": 1, "polarity": "-"}, {"label": "呲牙、低吼或咬手", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (3, '陌生人耐受度', 1, 'E/I', 3, '陌生人从主人手中短暂接过牵引绳，牵走狗狗 3 米，狗狗会？', NULL, NULL, '[{"label": "平静跟随，时不时回头看主人", "order": 0, "score": 3, "polarity": "+"}, {"label": "有些犹豫，但在陌生人引导下能走", "order": 1, "score": 1, "polarity": "+"}, {"label": "站在原地不肯走，需要陌生人拉拽", "order": 2, "score": 1, "polarity": "-"}, {"label": "激烈反抗、吠叫或试图挣脱", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (4, '同类狗狗社交耐受度', 2, 'E/I', 4, '户外遇到体型相近、情绪平稳的陌生狗狗，你的狗狗会？', NULL, NULL, '[{"label": "主动摇尾巴靠近，表现出玩耍兴趣", "order": 0, "score": 3, "polarity": "+"}, {"label": "保持礼貌距离，互相嗅闻后离开", "order": 1, "score": 1, "polarity": "+"}, {"label": "躲避、夹尾巴，想尽快离开", "order": 2, "score": 1, "polarity": "-"}, {"label": "吠叫、低吼或扑上去挑衅", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (5, '同类狗狗社交耐受度', 2, 'E/I', 5, '遇到体型远大于自己的陌生狗狗时，你的狗狗会？', NULL, NULL, '[{"label": "保持冷静，正常社交或礼貌回避", "order": 0, "score": 3, "polarity": "+"}, {"label": "有些紧张，但能在主人安抚下保持平静", "order": 1, "score": 1, "polarity": "+"}, {"label": "明显害怕，拽着主人想逃走", "order": 2, "score": 1, "polarity": "-"}, {"label": "不顾一切冲上去大叫或攻击", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (6, '同类狗狗社交耐受度', 2, 'E/I', 6, '和熟悉玩伴狗狗玩耍时被打断，你的狗狗会？', NULL, NULL, '[{"label": "听从主人指令，安静离开", "order": 0, "score": 3, "polarity": "+"}, {"label": "有些不舍，但很快配合主人", "order": 1, "score": 1, "polarity": "+"}, {"label": "需要反复催促才肯离开", "order": 2, "score": 1, "polarity": "-"}, {"label": "继续纠缠玩伴，对主人指令不理睬", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (7, '环境应激耐受度', 3, 'S/N', 7, '突然听到关门巨响、塑料袋风声、路人咳嗽或鞭炮声，狗狗会？', NULL, NULL, '[{"label": "耳朵动一下，但很快恢复平静", "order": 0, "score": 3, "polarity": "+"}, {"label": "短暂警觉，看向声音方向后放松", "order": 1, "score": 1, "polarity": "+"}, {"label": "明显受惊，躲到角落或主人怀里", "order": 2, "score": 1, "polarity": "-"}, {"label": "长时间狂吠、发抖或试图逃跑", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (8, '环境应激耐受度', 3, 'S/N', 8, '进入陌生嘈杂环境（商场、人流量大的街道），狗狗会？', NULL, NULL, '[{"label": "好奇探索，适应良好", "order": 0, "score": 3, "polarity": "+"}, {"label": "紧跟主人，略有紧张但能坚持", "order": 1, "score": 1, "polarity": "+"}, {"label": "明显不安，一直想离开", "order": 2, "score": 1, "polarity": "-"}, {"label": "趴地不走、发抖或出现攻击行为", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (9, '环境应激耐受度', 3, 'S/N', 9, '路上遇到雨伞、滑板、倒地杂物或反光物品，狗狗会？', NULL, NULL, '[{"label": "主动靠近嗅闻或无视", "order": 0, "score": 3, "polarity": "+"}, {"label": "绕开走，不影响正常前进", "order": 1, "score": 1, "polarity": "+"}, {"label": "停下脚步，需要主人引导", "order": 2, "score": 1, "polarity": "-"}, {"label": "狂吠不止，拒绝通过", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (10, '资源占有护食行为', 4, 'S/N', 10, '进食时主人伸手靠近食盆或拿走食物，狗狗会？', NULL, NULL, '[{"label": "毫无反应，甚至主动让开", "order": 0, "score": 3, "polarity": "+"}, {"label": "停顿一下，但没有护食行为", "order": 1, "score": 1, "polarity": "+"}, {"label": "发出低吼或加快进食速度", "order": 2, "score": 1, "polarity": "-"}, {"label": "呲牙、吠叫或试图咬人", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (11, '资源占有护食行为', 4, 'S/N', 11, '玩耍玩具时，主人强行拿走玩具，狗狗会？', NULL, NULL, '[{"label": "松口让给主人，等待再次互动", "order": 0, "score": 3, "polarity": "+"}, {"label": "有些不情愿，但还是松口", "order": 1, "score": 1, "polarity": "+"}, {"label": "咬住不放，需要命令才松口", "order": 2, "score": 1, "polarity": "-"}, {"label": "低吼、护玩具或咬手", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (12, '资源占有护食行为', 4, 'S/N', 12, '狗狗休息睡觉时，主人触碰它的爪子、肚子或耳朵，它会？', NULL, NULL, '[{"label": "放松接受，继续睡觉或摇尾巴", "order": 0, "score": 3, "polarity": "+"}, {"label": "抬头看一眼，但没有抵触", "order": 1, "score": 1, "polarity": "+"}, {"label": "身体僵硬，表现出不耐烦", "order": 2, "score": 1, "polarity": "-"}, {"label": "低吼、吠叫或咬人", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (13, '主人服从与自控能力', 5, 'P/J', 13, '户外平地牵引绳随行，没有特殊诱惑时，狗狗会？', NULL, NULL, '[{"label": "始终保持在主人身侧，不拉扯绳子", "order": 0, "score": 3, "polarity": "-"}, {"label": "偶尔超前或落后，但轻轻一拉就回来", "order": 1, "score": 3, "polarity": "-"}, {"label": "经常拉扯绳子，方向不定", "order": 2, "score": 1, "polarity": "+"}, {"label": "爆冲、四处乱窜，主人难以控制", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (14, '主人服从与自控能力', 5, 'P/J', 14, '主人原地静止站立 5 分钟，不给任何指令，狗狗会？', NULL, NULL, '[{"label": "安静坐在/站在主人身边等待", "order": 0, "score": 3, "polarity": "-"}, {"label": "偶尔走动，但不会离开主人太远", "order": 1, "score": 3, "polarity": "-"}, {"label": "频繁走动、嗅闻，注意力涣散", "order": 2, "score": 1, "polarity": "+"}, {"label": "拼命想挣脱牵引绳离开", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (15, '主人服从与自控能力', 5, 'P/J', 15, '户外看到零食、小动物或落叶等诱惑物时，狗狗会？', NULL, NULL, '[{"label": "看一眼主人，继续随行", "order": 0, "score": 3, "polarity": "-"}, {"label": "有冲动想去，但听从制止", "order": 1, "score": 3, "polarity": "-"}, {"label": "需要主人多次制止才肯放弃", "order": 2, "score": 1, "polarity": "+"}, {"label": "完全失控，拼命追上去", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (16, '分离情绪与居家行为', 6, 'F/T', 19, '主人短暂离开视线 5 分钟，关门把狗狗单独留在家中，它会？', NULL, NULL, '[{"label": "安静等待，主人回来时才迎接", "order": 0, "score": 3, "polarity": "-"}, {"label": "略有焦虑，但很快安静下来", "order": 1, "score": 3, "polarity": "-"}, {"label": "一直吠叫、抓门或踱步", "order": 2, "score": 1, "polarity": "+"}, {"label": "极度焦虑，破坏家具或随地大小便", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (17, '分离情绪与居家行为', 6, 'F/T', 20, '主人在家但不和狗狗互动时，狗狗会？', NULL, NULL, '[{"label": "自己安静休息或玩玩具", "order": 0, "score": 3, "polarity": "-"}, {"label": "偶尔过来撒娇，得不到回应就离开", "order": 1, "score": 3, "polarity": "-"}, {"label": "一直缠着主人，无法独处", "order": 2, "score": 1, "polarity": "+"}, {"label": "焦虑吠叫、破坏物品以引起注意", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-08 15:48:09', '2026-07-08 15:48:09');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (18, '分离情绪与居家行为', 6, 'F/T', 21, '当主人下班回家开门时，狗狗的第一反应是？', '', '', '[{"label": "狂摇尾巴、扑上来舔、围着主人转", "order": 0, "score": 3, "polarity": "+"}, {"label": "高兴地跑过来迎接，黏在脚边", "order": 1, "score": 1, "polarity": "+"}, {"label": "抬头看一眼，继续原来的事", "order": 2, "score": 1, "polarity": "-"}, {"label": "毫无反应，好像没听见", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (19, '分离情绪与居家行为', 6, 'F/T', 22, '带狗狗去陌生环境（如朋友家）时，它会？', '', '', '[{"label": "紧贴主人，不敢离开半步", "order": 0, "score": 3, "polarity": "+"}, {"label": "有些紧张，需要主人鼓励才肯探索", "order": 1, "score": 1, "polarity": "+"}, {"label": "好奇地四处嗅闻，偶尔回来看看主人", "order": 2, "score": 1, "polarity": "-"}, {"label": "完全不在意主人，自己玩自己的", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (20, '分离情绪与居家行为', 6, 'F/T', 23, '当狗狗身体不适或害怕时，它会？', '', '', '[{"label": "立刻跑来找主人，寻求安慰", "order": 0, "score": 3, "polarity": "+"}, {"label": "表现出异常，等待主人发现并照顾", "order": 1, "score": 1, "polarity": "+"}, {"label": "自己躲起来，不想被打扰", "order": 2, "score": 1, "polarity": "-"}, {"label": "忍耐，不表现出明显异常", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (21, '分离情绪与居家行为', 6, 'F/T', 24, '当有其他家庭成员靠近主人时，狗狗会？', '', '', '[{"label": "挤到中间，要求也关注自己", "order": 0, "score": 3, "polarity": "+"}, {"label": "凑过来一起互动", "order": 1, "score": 1, "polarity": "+"}, {"label": "无所谓，继续做自己的事", "order": 2, "score": 1, "polarity": "-"}, {"label": "主动离开，让出空间", "order": 3, "score": 3, "polarity": "-"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (22, '主人服从与自控能力', 5, 'P/J', 16, '每天到了固定散步时间，狗狗会？', '', '', '[{"label": "提前到门口等待，催促主人出门", "order": 0, "score": 3, "polarity": "-"}, {"label": "时间差不多就兴奋起来，提醒主人", "order": 1, "score": 3, "polarity": "-"}, {"label": "无所谓，主人说走才走", "order": 2, "score": 1, "polarity": "+"}, {"label": "经常忘记要散步这件事", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (23, '主人服从与自控能力', 5, 'P/J', 17, '狗狗的玩具或零食通常是怎么摆放的？', '', '', '[{"label": "玩完后会叼回固定位置", "order": 0, "score": 3, "polarity": "-"}, {"label": "有几个常放的角落", "order": 1, "score": 3, "polarity": "-"}, {"label": "丢得到处都是", "order": 2, "score": 1, "polarity": "+"}, {"label": "过几天就找不到了", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_questions (id,module_name,module_order,dimension,question_order,title,image_url,video_url,options,max_score,is_active,created_at,updated_at) VALUES (24, '主人服从与自控能力', 5, 'P/J', 18, '训练新指令时，狗狗的表现是？', '', '', '[{"label": "几次就能记住并稳定执行", "order": 0, "score": 3, "polarity": "-"}, {"label": "需要练习一段时间，但能掌握", "order": 1, "score": 3, "polarity": "-"}, {"label": "学会后过几天就忘了", "order": 2, "score": 1, "polarity": "+"}, {"label": "很难集中注意力，随性而为", "order": 3, "score": 1, "polarity": "+"}]', 3, 1, '2026-07-16 10:32:11', '2026-07-16 10:32:11');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (5, 'ESFP', '欢乐小太阳', '它像是家里永远充好电的小太阳，走到哪儿就把快乐带到哪儿。对新鲜事物充满好奇，喜欢被关注、被夸奖，也最爱用撒娇换取你的陪伴。它不太爱纠结过去或未来，只认真享受眼前的每一刻。', '①高频互动游戏：每天至少2次15分钟的抛接球、拔河等互动游戏，满足它的表演欲和精力。②正向社交拓展：定期安排性格温和的狗友聚会，让它在正向反馈中学会礼貌社交。③即时夸奖反馈：它很在意关注，做对立刻表扬，做错冷处理比批评更有效。④轮换感官玩具：准备多种材质、会发声的玩具，每周轮换，保持它对玩具的新鲜感。', '宠物短途旅行、泳池畅玩套餐、全年 9.9 陪伴会员', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:07');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (6, 'ESFJ', '贴心小棉袄', '它很擅长读懂家里的气氛，你开心它跟着开心，你低落它默默陪在身边。喜欢稳定的生活节奏，也渴望被全家人认可。对它来说，最好的奖励就是你的拥抱和一句“好乖”。', '①全家一致陪伴：它在意家里每个人的态度，统一作息和奖励方式会让它更有安全感。②仪式感奖励：完成指令后配合口头表扬和抚摸，它会因为被需要而更努力。③稳定生活节奏：固定喂食、散步、睡觉时间，规律的生活环境最能滋养它。④温和社交练习：选择性格稳定的狗友进行社交，避免粗暴玩耍让它受伤或紧张。', '亲子宠物团建、温和洗护套餐、陪伴型零食礼包', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:05');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (7, 'ENFP', '热情梦想家', '它的脑袋里仿佛装满了奇思妙想，今天爱这个玩具，明天又想追那片落叶。情感丰富，特别在意你的态度，一句夸奖能让它开心一整天。多陪它玩游戏、探索新环境，它会越来越信任你。', '①创意互动游戏：经常变换游戏方式，藏食、寻宝、模仿动作，满足它跳跃的想象力。②情绪回应优先：它很敏感，批评容易让它沮丧，多用拥抱和温柔语调沟通。③新鲜环境刺激：每周至少去一个新地方散步或郊游，新气味和新朋友是它的能量来源。④建立轻量规律：在它随性的天性里加入固定喂食和睡觉时间，帮助它稳定情绪。', '小众徒步出游、嗅闻益智玩具礼盒、行为脱敏课程', 1, '2026-07-15 10:38:48', '2026-07-17 11:14:59');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (8, 'ENFJ', '温暖领导者', '它像家里的小小领袖，既能带动气氛，又会关心每一个家庭成员。非常在意你的反馈，愿意为了让你开心而努力。给它正面的引导，它会成长为越来越懂事、越来越温柔的伙伴。', '①领导力正向引导：允许它在小范围内照顾家人，同时教它明确听从你的指令。②情感互动时间：每天留出专属陪伴时间，它是为爱和认可而活的狗狗。③团体训练课程：报名服从训练班，既能社交又能让它学会在群体中表现良好。④口头表扬为主：它特别吃甜言蜜语，一句你真棒比零食更能让它开心。', '多犬结伴出游、舒缓洗护、一对一情绪安抚训练', 1, '2026-07-15 10:38:48', '2026-07-17 11:14:57');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (9, 'ESTP', '冒险行动派', '它行动力满分，看到感兴趣的东西就想立刻去探个究竟。聪明、机敏，学东西很快，但耐心有限，重复训练容易让它觉得无聊。给它足够的新奇挑战，它会成为你最给力的户外搭档。', '①高强度户外运动：每天保证45分钟以上奔跑、嗅闻、障碍类运动，消耗过剩精力。②短时挑战训练：把训练拆成5-10分钟的小挑战，难度逐步升级，避免枯燥重复。③安全探索空间：带它去新路线散步，但要牵好绳，防止它因冲动追逐而跑丢。④益智漏食玩具：用漏食球、嗅闻垫让它边动脑边吃，能有效减少拆家行为。', '野外徒步、游泳训练、随行爆冲矫正课', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:12');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (10, 'ESTJ', '可靠小管家', '它天生有条理，喜欢明确的规则和可预期的生活。训练时配合度高，一旦学会就会认真执行。它可能看起来有点严肃，但内心深处把守护家人当成最重要的任务。', '①清晰指令训练：用简短一致的口令和明确手势，它学得又快又准。②任务式互动：给它分配小任务，如拿快递、守门口，满足它的责任心。③规律外出计划：每天固定时间、固定路线散步，可预期的生活让它最放松。④公正奖惩分明：对和错要界限清楚，奖励及时、错误立即纠正，它会非常服气。', '定点训练课程、居家行为规范辅导、规律洗护月卡', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:09');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (11, 'ENTP', '机灵辩论家', '它聪明到有点“狡黠”，很会试探你的底线，也享受和你斗智斗勇的过程。普通训练可能镇不住它，要用变化多端的游戏和正向引导。被它“套路”的时候，别忘了那也是它爱你的方式。', '①斗智斗勇游戏：用变化规则的小游戏和它互动，比如先坐下再握手才能获得零食。②进阶技能训练：教它复杂指令或敏捷障碍，聪明的大脑需要持续被挑战。③明确边界规则：它爱试探，全家要统一指令和底线，避免它看人下菜碟。④用游戏代替压制：遇到叛逆行为时，用更有趣的替代行为引导，而非强硬压制。', '益智解谜玩具套餐、趣味障碍训练、短途猎奇出游', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:03');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (12, 'ENTJ', '霸气指挥官', '它气场十足，做事果断，喜欢掌控局面。训练时要让它明白“你才是规则制定者”，同时给它有挑战性的任务。被它选中成为主人，其实是一种荣幸——它只臣服于真正值得信任的人。', '①挑战性目标训练：设置有难度的技能目标，如远距离召回、复杂动作串，激发它的征服欲。②确立主人权威：训练时冷静坚定，让它明白你才是规则的制定者。③结构化日程：用清晰的日程表管理运动、训练和休息，它会执行得非常漂亮。④高强度体能消耗：每天充分运动是释放它精力的关键，否则它可能把精力用在管理家具上。', '高阶服从训练、单独定制私教出游、领地行为矫正', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:01');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (13, 'ISFP', '温柔艺术家', '它性格温和、不善争抢，喜欢静静地待在你身边，感受阳光和微风。它对环境变化比较敏感，需要安全感和耐心。不要强迫它社交，给它足够的空间和温柔，它会用自己的方式爱你。', '①安全避风港：在家里为它准备一个安静角落，遇到压力时它可以 retreat 恢复。②低压力脱敏：对声音、陌生人等刺激采用渐进式脱敏，切勿强迫面对。③温柔陪伴互动：它不爱激烈游戏，安静的抚摸、一起晒太阳就是它最幸福的时刻。④自然环境散步：选择人少、安静的自然路线散步，让它用舒适的节奏探索世界。', '安静小众单人出游、舒缓 SPA 洗护、环境脱敏私教课', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:24');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (14, 'ISFJ', '忠诚守护者', '它是最传统的“好狗狗”代表，安静、忠诚、把家人放在第一位。不需要太多刺激，规律的陪伴和认可就是它最大的幸福。它可能不会撒娇，但每一个眼神都在说“我陪着你”。', '①守护任务认可：给它适当的看家任务并及时认可，它会非常有成就感。②高度规律作息：固定的喂食、散步、休息时间是它安全感的来源，尽量不要打乱。③温和渐进社交：带它认识新朋友时节奏放慢，建立信任后它会非常忠诚。④适量稳定运动：每天中等强度散步即可，过多刺激反而会让它疲惫焦虑。', '固定周期洗护、短途安静散步套餐、独处安抚玩具', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:22');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (15, 'INFP', '治愈小天使', '它有一颗柔软的心，对亲近的人非常忠诚，只是不太擅长表达。它会在你难过时轻轻靠过来，用行动告诉你“我在”。给它温柔而稳定的爱，它会成为最治愈的存在。', '①温柔建立信任：用耐心和低压力方式靠近它，强制互动只会让它退缩。②固定陪伴仪式：每天固定时间的安静陪伴，比如一起读书、听音乐，让它感到安全。③避免惩罚教育：它内心敏感，严厉批评会造成长期焦虑，正向引导效果最好。④稳定的生活环境：尽量减少搬家、换家具等变动，稳定是它情感健康的基础。', '低刺激舒缓洗护、情绪安抚香氛套餐、一对一心理疏导', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:16');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (16, 'INFJ', '神秘知心者', '它看起来安静，其实对家里每个人的情绪都了如指掌。不轻易付出信任，但一旦认定你，就会非常深情。它需要被理解，而不是被命令；给它耐心，它会回报你无条件的陪伴。', '①读懂它的信号：它常通过眼神和肢体语言表达，学会观察比强迫它回应更重要。②深度一对一陪伴：它不需要热闹，每天一段只有你俩的安静时光最珍贵。③低压环境优先：避免人多嘈杂的场合，安静的自然环境最能展现它的温柔。④耐心信任训练：训练时给它思考时间，不要催它，信任建立后学习速度会突飞猛进。', '定制单人安静出游、舒缓洗护月卡、分离焦虑矫正', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:14');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (17, 'ISTP', '冷静观察家', '它话不多，但眼睛总在观察周围。遇到问题时冷静又独立，喜欢自己研究玩具或环境。训练时它需要知道“这样做有什么好处”，用正向奖励比命令更有效。', '①动手类益智玩具：漏食球、拆解玩具能满足它研究和动手的欲望。②奖励驱动训练：训练时用高价值零食明确有好处，它比单纯服从命令更积极。③允许观察空间：去新环境时先让它安静观察，不要急着拉它社交。④适度冒险活动：带它尝试徒步、嗅闻寻宝等有探索感的活动，释放它冷静外表下的活力。', '啃咬益智玩具、户外单人探索路线、护食行为矫正', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:28');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (18, 'ISTJ', '稳重实干家', '它踏实、自律，习惯用行动表达爱。每天的散步路线、喂食时间，它都记得清清楚楚。训练时配合度高，犯错后也会努力改正。和它相处，你会感受到一种稳稳的安心。', '①严格执行日程：制定并坚持每日时间表，它会因可预期而表现得非常稳定。②系统服从训练：从基础指令开始系统训练，它喜欢明确的标准和稳定的进步。③完成任务式奖励：在它认真完成任务后给予奖励，它会把这视为一种荣誉。④固定路线散步：选择固定路线散步，熟悉的标记和节奏让它最舒适。', '周期固定洗护、居家规矩训练、低刺激独处礼包', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:26');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (19, 'INTP', '好奇哲学家', '它对世界充满好奇，常常盯着一个东西研究很久。情绪稳定，不太黏人，但偶尔会给出一些让你意外的聪明反应。别嫌它慢热，它在用自己的节奏理解和爱你。', '①满足好奇心：提供能研究、拆解、探索的玩具，满足它哲学家式的好奇心。②puzzle训练：用需要动脑的技能训练吸引它，比如按铃、开门、找物品。③尊重独处时间：它不需要时刻被关注，给它独立空间反而能让它更放松。④目标导向奖励：训练时让它明白每一步都有明确回报，它会自己思考最优解法。', '解谜玩具礼盒、安静室内嗅闻游戏、低强度居家训练', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:20');
REPLACE INTO dog_personality_levels (id,code,title,description,guide,recommendation,is_active,created_at,updated_at) VALUES (20, 'INTJ', '独立战略家', '它独立、冷静，有着自己的小世界。不喜欢无意义的互动，但对感兴趣的事会钻研到底。它可能不是最黏人的狗，但会用独特的方式表达忠诚。尊重它的空间，它会主动靠近你。', '①高难度技能挑战：教它需要思考和规划的复杂动作，如按顺序取物、开门等。②自主探索空间：提供能独立研究的玩具和环境，满足它自己搞定的天性。③尊重它的节奏：不要强迫社交或过度热情，它会按自己的节奏靠近你。④低干扰生活环境：保持环境安静有序，减少无意义的刺激，是它最佳状态的前提。', '高阶逻辑训练、私人定制安静出游、领地安全感辅导', 1, '2026-07-15 10:38:48', '2026-07-17 11:15:18');
REPLACE INTO dog_personality_behavior_tags (id,tag_key,tag_text,category,threshold,priority,is_active,created_at,updated_at) VALUES (1, 'stranger_aggressive', '面对陌生人会保持高度警戒，容易出现吠叫、低吼等防御信号。', 'problem', 2, 10, 1, '2026-07-17 14:47:43', '2026-07-17 14:47:43');
REPLACE INTO dog_personality_behavior_tags (id,tag_key,tag_text,category,threshold,priority,is_active,created_at,updated_at) VALUES (2, 'stranger_avoidant', '面对陌生人倾向于回避或躲藏，需要循序渐进的正向社交。', 'problem', 2, 5, 1, '2026-07-17 14:47:43', '2026-07-17 14:47:43');
REPLACE INTO dog_personality_behavior_tags (id,tag_key,tag_text,category,threshold,priority,is_active,created_at,updated_at) VALUES (3, 'dog_aggressive', '遇到同类时反应较强，容易吠叫或挑衅。', 'problem', 2, 10, 1, '2026-07-17 14:47:43', '2026-07-17 14:47:43');
REPLACE INTO dog_personality_behavior_tags (id,tag_key,tag_text,category,threshold,priority,is_active,created_at,updated_at) VALUES (4, 'dog_fearful', '遇到体型较大的同类容易感到害怕，想要逃离现场。', 'problem', 2, 5, 1, '2026-07-17 14:47:43', '2026-07-17 14:47:43');
